def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 18.0))

    slots = supply / float(WATER_REQ)
    contested = slots < 2.0

    pressure_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for opp in alive:
        prev = opp.get('previous_trace', {})
        prev_bid = 0.0
        if prev and prev.get('bid') is not None:
            prev_bid = float(prev.get('bid', 0.0))
            pressure_bids.append(prev_bid)

        opp_hp = opp.get('hp', 0)
        opp_nw = opp.get('no_water_days', 0)
        opp_budget = opp.get('budget', 0.0)
        if opp_hp <= 3 or opp_nw >= 1:
            desperate_count += 1
        if opp_budget >= 200 and prev_bid >= 80:
            rich_aggressive += 1

    max_prev = max(pressure_bids) if pressure_bids else 0.0
    avg_prev = sum(pressure_bids) / float(len(pressure_bids)) if pressure_bids else 0.0

    emergency = (hp <= 3) or (no_water >= 1)

    if emergency:
        bid = max(78.0, max_prev + 3.0)
        if contested:
            bid += 10.0
        return float(min(budget, bid))

    if contested:
        if rich_aggressive >= 1:
            bid = 24.0
        else:
            bid = max(28.0, min(62.0, avg_prev + 2.0))
            if desperate_count >= 2:
                bid += 8.0
    else:
        if max_prev >= 100.0:
            bid = 14.0
        elif max_prev >= 70.0:
            bid = 18.0
        else:
            bid = 22.0

    if day >= 8 and hp >= 6:
        bid *= 0.9
    if budget < 120:
        bid = min(bid, 36.0)

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids to infer who is pressuring.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    # Also check if Cindy (likely main competitor) was bidding high.
    cindy_prev = 0.0
    for oid, o in alive_opps:
        if str(oid) == 'Cindy':
            prev = o.get('previous_trace', {}) or {}
            b = prev.get('bid', None)
            if b is not None:
                try:
                    cindy_prev = float(b)
                except Exception:
                    cindy_prev = 0.0

    # Supply pressure: if supply is low, more agents will need to win water.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)  # 0..1
    low_supply = supply_ratio < 0.35

    # Base bid targets.
    # Strategy: If Cindy was pressuring (high yesterday bid), match partially.
    if cindy_prev >= DAILY_SALARY * 1.25 or highest_prev_bid >= DAILY_SALARY * 1.35:
        target = DAILY_SALARY * (0.55 if hp > 3 else 0.85)
    elif low_supply:
        target = DAILY_SALARY * (0.65 if hp > 3 else 0.9)
    else:
        target = DAILY_SALARY * (0.45 if hp > 3 else 0.75)

    # If I'm already close to death, increase urgency sharply.
    if hp <= 2.0 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.95)

    # Budget safety: never bid more than budget.
    bid = min(budget, target)

    # If budget is tiny, bid what we can.
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
